head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
scwin.vScrenID = 'ULDSTF25955.xml'; // 화면명

scwin.select_yyyy = ''; // 선택한 연도
scwin.past_1yyyy = ''; // 선택한 연도의 1년전 연도
scwin.past_2yyyy = ''; // 선택한 연도의 2년전 연도
scwin.past_3yyyy = ''; // 선택한 연도의 3년전 연도
scwin.past_4yyyy = '';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; // 선택한 연도의 4년전 연도

scwin.initPage = function() {
    scwin.fn_SetYear();
};
scwin.fn_SetYear = function() {
    // 화면 진입 후 연도 조회 중일때 selectbox에 빈칸으로 보여서 '조회중' 이라는 문구를 넣음
    // ^temp 에서 temp는 의미 없는 값이지만, ^뒤에 데이타가 있어야 문구가 노출됨.
    cmb_YearList.CBData = "연도 조회중...^temp";

    // 연도조회(데이타가 등록 되어 있다면 연도가 조회 될 것이고 등록 안되어 있다면 연도가 없음)
    dts_year.DataID = "/EsgSearch.do?method=getYearList";
    dts_year.Reset();
};
scwin.fn_Search = function() {
    // 연도 validation
    var year = $c.cp.valueOfIndex(cmb_YearList, "YEAR", cmb_YearList.getSelectedIndex()); // 선택한 연도
    if (year == '') {
        $c.win.alert("연도를 선택해주세요");
        return;
    }
    $c.cm.ShowWin(grd_Grid); // loading중 display
    // 회사별 핵심지표 준수율 현황(5개년) 통계 조회
    var url = "/EsgStatistics.do?method=companyByCoreIndicStat";
    url += "&YEAR=" + year; // 선택한 연도
    url += "&PAST_1YEAR=" + scwin.past_1yyyy; // 선택한 연도에서 1년전 연도
    url += "&PAST_2YEAR=" + scwin.past_2yyyy; // 선택한 연도에서 2년전 연도
    url += "&PAST_3YEAR=" + scwin.past_3yyyy; // 선택한 연도에서 3년전 연도
    url += "&PAST_4YEAR=" + scwin.past_4yyyy; // 선택한 연도에서 4년전 연도

    dts_Grid.DataID = url;
    dts_Grid.Reset();
};
scwin.fn_Excel = function() {
    //엑셀 다운로드
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewOffice(grd_Grid, "회사별 핵심지표 준수율 현황(5개년) 통계", "회사별 핵심지표 준수율 현황(5개년) 통계.xlsx", "8", 0);
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    // 조회를 성공하면 선택한 년도를 헤더에 그려준다.
    var year = $c.cp.valueOfIndex(cmb_YearList, "YEAR", cmb_YearList.getSelectedIndex());
    var date = new Date();
    date.setFullYear(parseInt(year));
    scwin.select_yyyy = year; // 현재연도
    scwin.past_1yyyy = date.getFullYear() - 1; // 1년전연도
    scwin.past_2yyyy = date.getFullYear() - 2; // 2년전연도
    scwin.past_3yyyy = date.getFullYear() - 3; // 3년전연도
    scwin.past_4yyyy = date.getFullYear() - 4; // 4년전연도

    // 헤더에 현재 연도~4년전 연도를 표시
    $c.cm.setColumnProp(grd_Grid, 'Y', 'Name', 'Y (' + scwin.select_yyyy + '년)');
    $c.cm.setColumnProp(grd_Grid, 'Y_1', 'Name', 'Y-1 (' + scwin.past_1yyyy + '년)');
    $c.cm.setColumnProp(grd_Grid, 'Y_2', 'Name', 'Y-2 (' + scwin.past_2yyyy + '년)');
    $c.cm.setColumnProp(grd_Grid, 'Y_3', 'Name', 'Y-3 (' + scwin.past_3yyyy + '년)');
    $c.cm.setColumnProp(grd_Grid, 'Y_4', 'Name', 'Y-4 (' + scwin.past_4yyyy + '년)');
    $c.cm.CloseWin(rowcount, grd_Grid); //조회완료시 LOADING 이미지 종료
    //FillGridHeaderTotalCnt(rowcount, panel_page);	//총 건수

};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1); // 검색조건 패널에 스타일 적용
    scwin.initPage();
};
scwin.dts_year_OnLoadCompleted = function(rowcount) {
    // 연도가 없다는건 실제 데이타가 없다는 것이기 때문에 별도 텍스트를 보여줌
    if (rowcount == 0) {
        dts_year.insertRow();
        dts_year.setCellData(1, "YEAR_TEXT", '연도가 존재하지 않습니다');
        dts_year.setCellData(1, "YEAR", '');
    } else {
        // 연도가 있을 경우 헤더에 default로 최근 연도를 표시
        var year = $c.cp.valueOfIndex(cmb_YearList, "YEAR", cmb_YearList.getSelectedIndex());
        var date = new Date();
        date.setFullYear(parseInt(year));
        scwin.select_yyyy = year; // 현재연도
        scwin.past_1yyyy = date.getFullYear() - 1; // 1년전연도
        scwin.past_2yyyy = date.getFullYear() - 2; // 2년전연도
        scwin.past_3yyyy = date.getFullYear() - 3; // 3년전연도
        scwin.past_4yyyy = date.getFullYear() - 4; // 4년전연도

        // 헤더에 현재 연도~4년전 연도를 표시
        $c.cm.setColumnProp(grd_Grid, 'Y', 'Name', 'Y (' + scwin.select_yyyy + '년)');
        $c.cm.setColumnProp(grd_Grid, 'Y_1', 'Name', 'Y-1 (' + scwin.past_1yyyy + '년)');
        $c.cm.setColumnProp(grd_Grid, 'Y_2', 'Name', 'Y-2 (' + scwin.past_2yyyy + '년)');
        $c.cm.setColumnProp(grd_Grid, 'Y_3', 'Name', 'Y-3 (' + scwin.past_3yyyy + '년)');
        $c.cm.setColumnProp(grd_Grid, 'Y_4', 'Name', 'Y-4 (' + scwin.past_4yyyy + '년)');
    }
};
scwin.cmb_YearList_OnSelChange = function() {
    // 연도가 변경 되면 선택한 연도~4년전 연도를 셋팅
    var year = $c.cp.valueOfIndex(cmb_YearList, "YEAR", cmb_YearList.getSelectedIndex());
    var date = new Date();
    date.setFullYear(parseInt(year));
    scwin.select_yyyy = year; // 현재연도
    scwin.past_1yyyy = date.getFullYear() - 1; // 1년전연도
    scwin.past_2yyyy = date.getFullYear() - 2; // 2년전연도
    scwin.past_3yyyy = date.getFullYear() - 3; // 3년전연도
    scwin.past_4yyyy = date.getFullYear() - 4; // 4년전연도

};
scwin.btn_Excel_onclick = function() {
    scwin.fn_Excel();
};
